INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('engagement-volve', 'Campaña de enganche — engagement-volve', $asunto$💛 Te extrañamos en AdorAPP$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://www.adorapp.net.ar/engagement-banner-volve.png" width="600" alt="Adoración CAF — No es lo mismo sin vos" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Notamos que hace un tiempo no te das una vuelta por AdorAPP, y queríamos decirte algo simple: <b>te extrañamos</b>. El ministerio no es lo mismo sin vos. 💛</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://www.adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«No dejando de congregarnos, como algunos tienen por costumbre, sino exhortándonos.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Hebreos 10:25</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">Adentro está todo lo que el equipo prepara para cada servicio: <b>las órdenes</b> con las canciones, el <b>repertorio</b> con letras y acordes, tus <b>ensayos</b>, los <b>ensambles</b> y todos los avisos del ministerio. Volvé a entrar — en un toque estás al día otra vez.</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Te necesitamos. <b>No te quedes afuera.</b> 🙌</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Volver a AdorAPP</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Notamos que hace un tiempo no te das una vuelta por AdorAPP, y queriamos decirte algo simple: te extranamos. El ministerio no es lo mismo sin vos.

"No dejando de congregarnos, como algunos tienen por costumbre, sino exhortándonos." (Hebreos 10:25)

Adentro esta todo lo que el equipo prepara para cada servicio: las ordenes con las canciones, el repertorio con letras y acordes, tus ensayos, los ensambles y todos los avisos del ministerio. Volve a entrar: en un toque estas al dia otra vez. Te necesitamos. No te quedes afuera.

Volver a AdorAPP: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
ON CONFLICT (slug) DO UPDATE SET descripcion=EXCLUDED.descripcion, asunto=EXCLUDED.asunto, from_label=EXCLUDED.from_label, activo=EXCLUDED.activo, color_acento=EXCLUDED.color_acento, mostrar_logo=EXCLUDED.mostrar_logo, body_html=EXCLUDED.body_html, body_text=EXCLUDED.body_text, cuerpo_html=NULL, updated_at=now();

INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('engagement-instalar', 'Campaña de enganche — engagement-instalar', $asunto$📲 Llevá AdorAPP en tu teléfono$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://www.adorapp.net.ar/engagement-banner-instalar.png" width="600" alt="Adoración CAF — AdorAPP a un toque" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Entrás a AdorAPP desde el navegador — ¡genial! Pero te estás perdiendo lo más cómodo: <b>tenerla instalada en tu teléfono</b>, como una app más. 📲</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://www.adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«Yo me alegré con los que me decían: A la casa de Jehová iremos.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Salmo 122:1</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">Instalala en tu pantalla de inicio y la abrís <b>con un solo toque</b> —sin buscar el navegador—, carga al instante y anda hasta con poca señal. El ministerio, <b>siempre a mano</b>. Desde el teléfono es un minuto: tocás «Compartir» y después «Agregar a inicio» (o seguís el cartel que aparece al entrar).</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Una vez y listo. <b>No te lo pierdas.</b> ✨</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Instalar AdorAPP</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Entras a AdorAPP desde el navegador, genial! Pero te estas perdiendo lo mas comodo: tenerla instalada en tu telefono, como una app mas.

"Yo me alegré con los que me decían: A la casa de Jehová iremos." (Salmo 122:1)

Instalala en tu pantalla de inicio y la abris con un solo toque (sin buscar el navegador), carga al instante y anda hasta con poca senal. El ministerio, siempre a mano. Desde el telefono es un minuto: tocas Compartir y despues Agregar a inicio (o seguis el cartel que aparece al entrar). Una vez y listo. No te lo pierdas.

Instalar AdorAPP: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
ON CONFLICT (slug) DO UPDATE SET descripcion=EXCLUDED.descripcion, asunto=EXCLUDED.asunto, from_label=EXCLUDED.from_label, activo=EXCLUDED.activo, color_acento=EXCLUDED.color_acento, mostrar_logo=EXCLUDED.mostrar_logo, body_html=EXCLUDED.body_html, body_text=EXCLUDED.body_text, cuerpo_html=NULL, updated_at=now();

INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('engagement-notificaciones', 'Campaña de enganche — engagement-notificaciones', $asunto$🔔 Activá las notificaciones y no te pierdas nada$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://www.adorapp.net.ar/engagement-banner-notif.png" width="600" alt="Adoración CAF — Enterate al instante" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Ya tenés la app — <b>buenísimo</b>. Pero sin las notificaciones activadas te estás perdiendo lo que pasa en el momento. 🔔</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://www.adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«Bienaventurado el hombre que me escucha, velando a mis puertas cada día.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Proverbios 8:34</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">Activalas y <b>enterate al instante</b>: cuando se publica un <b>orden nuevo</b>, cuando hay <b>ensamble</b>, cuando cambia algo del servicio, cuando te suman a una <b>formación</b>, los cumpleaños del equipo y cada aviso del ministerio. Sin entrar a revisar: el ministerio te avisa a vos.</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Es un toque. <b>Que no se te escape nada.</b> 🙌</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Activar notificaciones</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Ya tenes la app, buenisimo. Pero sin las notificaciones activadas te estas perdiendo lo que pasa en el momento.

"Bienaventurado el hombre que me escucha, velando a mis puertas cada día." (Proverbios 8:34)

Activalas y enterate al instante: cuando se publica un orden nuevo, cuando hay ensamble, cuando cambia algo del servicio, cuando te suman a una formacion, los cumpleanos del equipo y cada aviso del ministerio. Sin entrar a revisar: el ministerio te avisa a vos. Es un toque. Que no se te escape nada.

Activar notificaciones: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
ON CONFLICT (slug) DO UPDATE SET descripcion=EXCLUDED.descripcion, asunto=EXCLUDED.asunto, from_label=EXCLUDED.from_label, activo=EXCLUDED.activo, color_acento=EXCLUDED.color_acento, mostrar_logo=EXCLUDED.mostrar_logo, body_html=EXCLUDED.body_html, body_text=EXCLUDED.body_text, cuerpo_html=NULL, updated_at=now();

INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('engagement-instalar-notif', 'Campaña de enganche — engagement-instalar-notif', $asunto$✨ Dos pasos para vivir el ministerio a pleno$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://www.adorapp.net.ar/engagement-banner-ambos.png" width="600" alt="Adoración CAF — Sumate del todo" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Queremos que tengas <b>la mejor experiencia</b> del ministerio, y hoy te estás perdiendo dos cosas que hacen toda la diferencia. ✨</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://www.adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«Vosotros, pues, sois el cuerpo de Cristo, y miembros cada uno en particular.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">1 Corintios 12:27</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">① <b>Instalá AdorAPP</b> en tu teléfono: la tenés a un toque, siempre a mano. ② <b>Activá las notificaciones</b>: te enterás al instante de órdenes, ensambles, cambios y avisos. Son <b>dos pasos de un minuto</b> y cambian por completo cómo vivís el ministerio desde el celular.</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Sos parte de este cuerpo. <b>Sumate del todo.</b> 🙌</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Completar en 1 minuto</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Queremos que tengas la mejor experiencia del ministerio, y hoy te estas perdiendo dos cosas que hacen toda la diferencia.

"Vosotros, pues, sois el cuerpo de Cristo, y miembros cada uno en particular." (1 Corintios 12:27)

1) Instala AdorAPP en tu telefono: la tenes a un toque, siempre a mano. 2) Activa las notificaciones: te enteras al instante de ordenes, ensambles, cambios y avisos. Son dos pasos de un minuto y cambian por completo como vivis el ministerio desde el celular. Sos parte de este cuerpo. Sumate del todo.

Completar en 1 minuto: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
